#!/usr/bin/env node
'use strict';
/**
 * Runs Vitest across script extensions in the workspace.
 */
const { existsSync, readdirSync } = require('fs');
const { execSync } = require('child_process');

const hasExtensions =
  existsSync('extensions') &&
  readdirSync('extensions').some((name) => existsSync(`extensions/${name}/package.json`));

const hasReleaseTools = existsSync('tools/release/package.json');

let exitCode = 0;

function run(cmd) {
  try {
    execSync(cmd, { stdio: 'inherit' });
  } catch (e) {
    exitCode = e.status ?? 1;
  }
}

if (hasExtensions || hasReleaseTools) {
  run('vitest run');
}

process.exit(exitCode);

import { describe, expect, test } from 'vitest';
import type { Billing, Commerce, Context } from '@stripe/extensibility-sdk';
import { Decimal } from '@stripe/extensibility-sdk';

import PriceTargetedPercentOff, { type PriceTargetedPercentOffConfig } from './index.js';

const context: Context = { type: 'script', id: 'test', livemode: false };
const period = { value: 'oneTime' as const, at: new Date('2026-01-01T00:00:00Z') };

function line(
  subtotal: number,
  metadata: Record<string, string>,
  currency: Billing.Currency = 'usd'
): Commerce.DiscountCalculation.DiscountableLineItem {
  return {
    subtotal: { amount: Decimal.from(subtotal), currency },
    quantity: Decimal.from(1),
    period,
    price: {
      id: `price_${subtotal}`,
      metadata,
      tiers: [],
    },
  };
}

const config: PriceTargetedPercentOffConfig = {
  percentageOff: 0.25,
  metadataMatcher: {
    key: 'promotion',
    value: 'summer',
  },
};

function calculate(
  lineItems: Commerce.DiscountCalculation.DiscountableLineItem[],
  override: Partial<PriceTargetedPercentOffConfig> = {},
  grossAmount = 100_000
) {
  return new PriceTargetedPercentOff().computeDiscounts(
    {
      grossAmount: { amount: Decimal.from(grossAmount), currency: 'usd' },
      lineItems,
      subscriptions: {},
    },
    { ...config, ...override },
    context
  ).discount.amount;
}

describe('PriceTargetedPercentOff', () => {
  test('sums percentage discounts for every matching price', () => {
    const discount = calculate([
      line(4_000, { promotion: 'summer' }),
      line(6_000, { promotion: 'summer' }),
      line(8_000, { promotion: 'winter' }),
    ]);

    expect(discount.amount.toString()).toBe('2500');
  });

  test('matches metadata keys and values exactly', () => {
    const discount = calculate([
      line(4_000, { Promotion: 'summer' }),
      line(4_000, { promotion: 'Summer' }),
      line(4_000, { promotion: 'summer' }),
    ]);

    expect(discount.amount.toString()).toBe('1000');
  });

  test('ignores missing prices and line items in another currency', () => {
    const withoutPrice: Commerce.DiscountCalculation.DiscountableLineItem = {
      subtotal: { amount: Decimal.from(4_000), currency: 'usd' },
      quantity: Decimal.from(1),
      period,
    };
    const discount = calculate([
      withoutPrice,
      line(4_000, { promotion: 'summer' }, 'eur'),
    ]);

    expect(discount.amount.toString()).toBe('0');
  });

  test('applies the maximum valid percentage of 1 before summing line discounts', () => {
    const discount = calculate(
      [line(8_000, { promotion: 'summer' }), line(8_000, { promotion: 'summer' })],
      { percentageOff: 1 }
    );

    expect(discount.amount.toString()).toBe('16000');
  });

  test('caps the aggregate discount at the invoice total', () => {
    const discount = calculate(
      [line(8_000, { promotion: 'summer' }), line(8_000, { promotion: 'summer' })],
      { percentageOff: 1 },
      10_000
    );

    expect(discount.amount.toString()).toBe('10000');
  });

  test('returns zero for no matching lines or zero percent', () => {
    expect(calculate([line(4_000, {})]).amount.toString()).toBe('0');
    expect(
      calculate([line(4_000, { promotion: 'summer' })], {
        percentageOff: 0,
      }).amount.toString()
    ).toBe('0');
  });

  test('returns zero when the metadata key is empty', () => {
    const discount = calculate([line(4_000, { promotion: 'summer' })], {
      metadataMatcher: { key: '', value: 'summer' },
    });

    expect(discount.amount.toString()).toBe('0');
  });

  test('returns zero for a negative percentage', () => {
    const discount = calculate([line(4_000, { promotion: 'summer' })], {
      percentageOff: -0.25,
    });

    expect(discount.amount.toString()).toBe('0');
  });

  test('ignores a matching line with a negative subtotal', () => {
    const discount = calculate([
      line(-4_000, { promotion: 'summer' }),
      line(4_000, { promotion: 'summer' }),
    ]);

    expect(discount.amount.toString()).toBe('1000');
  });

  test('ignores a matching line with a zero subtotal', () => {
    const discount = calculate([
      line(0, { promotion: 'summer' }),
      line(4_000, { promotion: 'summer' }),
    ]);

    expect(discount.amount.toString()).toBe('1000');
  });

  test('matches line-item and invoice currencies case-insensitively', () => {
    const discount = calculate([
      line(4_000, { promotion: 'summer' }, 'USD' as Billing.Currency),
    ]);

    expect(discount.amount.toString()).toBe('1000');
    expect(discount.currency).toBe('usd');
  });

  test.each([0, -1_000])('returns zero for a gross amount of %s', (grossAmount) => {
    const discount = calculate([line(4_000, { promotion: 'summer' })], {}, grossAmount);

    expect(discount.amount.toString()).toBe('0');
  });
});

import { describe, expect, test } from 'vitest';
import type { Billing, Context } from '@stripe/extensibility-sdk';
import { Decimal } from '@stripe/extensibility-sdk';

import PercentOffUpToMaximum, { type PercentOffUpToMaximumConfig } from './index.js';

const context: Context = { type: 'script', id: 'test', livemode: false };

function calculate(
  grossAmount: number,
  config: PercentOffUpToMaximumConfig,
  currency: Billing.Currency = 'usd'
) {
  return new PercentOffUpToMaximum().computeDiscounts(
    {
      grossAmount: { amount: Decimal.from(grossAmount), currency },
      lineItems: [],
      subscriptions: {},
    },
    config,
    context
  ).discount.amount;
}

describe('PercentOffUpToMaximum', () => {
  test('applies the percentage when it is below the maximum', () => {
    const discount = calculate(10_000, {
      percentageDiscount: 0.2,
      maximumDiscount: { amount: Decimal.from(5_000), currency: 'usd' },
    });

    expect(discount.amount.toString()).toBe('2000');
    expect(discount.currency).toBe('usd');
  });

  test('caps a ten percent discount at five dollars', () => {
    const discount = calculate(10_000, {
      percentageDiscount: 0.1,
      maximumDiscount: { amount: Decimal.from(500), currency: 'usd' },
    });

    expect(discount.amount.toString()).toBe('500');
  });

  test('applies the maximum valid percentage of 1 at the invoice total', () => {
    const discount = calculate(10_000, {
      percentageDiscount: 1,
      maximumDiscount: { amount: Decimal.from(20_000), currency: 'usd' },
    });

    expect(discount.amount.toString()).toBe('10000');
  });

  test('returns zero when currencies do not match', () => {
    const discount = calculate(10_000, {
      percentageDiscount: 0.2,
      maximumDiscount: { amount: Decimal.from(5_000), currency: 'eur' },
    });

    expect(discount.amount.toString()).toBe('0');
  });

  test('matches configured and invoice currencies case-insensitively', () => {
    const discount = calculate(10_000, {
      percentageDiscount: 0.2,
      maximumDiscount: {
        amount: Decimal.from(5_000),
        currency: 'USD' as Billing.Currency,
      },
    });

    expect(discount.amount.toString()).toBe('2000');
    expect(discount.currency).toBe('usd');
  });

  test('returns the invoice currency on a zero discount', () => {
    const discount = calculate(
      10_000,
      {
        percentageDiscount: 0,
        maximumDiscount: { amount: Decimal.from(5_000), currency: 'usd' },
      },
      'USD' as Billing.Currency
    );

    expect(discount.amount.toString()).toBe('0');
    expect(discount.currency).toBe('USD');
  });

  test.each([0, -0.1])('returns zero for a percentage of %s', (percentageDiscount) => {
    const discount = calculate(10_000, {
      percentageDiscount,
      maximumDiscount: { amount: Decimal.from(5_000), currency: 'usd' },
    });

    expect(discount.amount.toString()).toBe('0');
  });

  test.each([0, -500])(
    'returns zero for a maximum discount amount of %s',
    (maximumDiscount) => {
      const discount = calculate(10_000, {
        percentageDiscount: 0.2,
        maximumDiscount: { amount: Decimal.from(maximumDiscount), currency: 'usd' },
      });

      expect(discount.amount.toString()).toBe('0');
    }
  );

  test.each([0, -10_000])('returns zero for a gross amount of %s', (grossAmount) => {
    const discount = calculate(grossAmount, {
      percentageDiscount: 0.2,
      maximumDiscount: { amount: Decimal.from(5_000), currency: 'usd' },
    });

    expect(discount.amount.toString()).toBe('0');
  });
});

import { describe, expect, test } from 'vitest';
import type { Billing, Commerce, Context } from '@stripe/extensibility-sdk';
import { Decimal } from '@stripe/extensibility-sdk';

import BuyXGetYFree, { type BuyXGetYFreeConfig } from './index.js';

const context: Context = { type: 'script', id: 'test', livemode: false };
const period = { value: 'oneTime' as const, at: new Date('2026-01-01T00:00:00Z') };

function line({
  productId = 'product_a',
  quantity,
  subtotal,
  metadata = { promotion: 'bogo' },
  currency = 'usd',
}: {
  productId?: string;
  quantity: number | string;
  subtotal: number | string;
  metadata?: Record<string, string>;
  currency?: Billing.Currency;
}): Commerce.DiscountCalculation.DiscountableLineItem {
  return {
    subtotal: { amount: Decimal.from(subtotal), currency },
    quantity: Decimal.from(quantity),
    period,
    price: {
      id: `price_${productId}_${subtotal}`,
      metadata: {},
      tiers: [],
      product: { id: productId, name: productId, metadata },
    },
  };
}

const config: BuyXGetYFreeConfig = {
  purchaseQuantity: 3,
  freeQuantity: 2,
  metadataMatcher: {
    key: 'promotion',
    value: 'bogo',
  },
};

function calculate(
  lineItems: Commerce.DiscountCalculation.DiscountableLineItem[],
  grossAmount = 100_000,
  override: Partial<BuyXGetYFreeConfig> = {}
) {
  return new BuyXGetYFree().computeDiscounts(
    {
      grossAmount: { amount: Decimal.from(grossAmount), currency: 'usd' },
      lineItems,
      subscriptions: {},
    },
    { ...config, ...override },
    context
  ).discount.amount;
}

describe('BuyXGetYFree', () => {
  test('does not discount when the purchased quantity is at the threshold', () => {
    expect(calculate([line({ quantity: 3, subtotal: 3_000 })]).amount.toString()).toBe(
      '0'
    );
  });

  test('discounts only the additional units up to the configured free quantity', () => {
    expect(calculate([line({ quantity: 4, subtotal: 4_000 })]).amount.toString()).toBe(
      '1000'
    );
    expect(calculate([line({ quantity: 5, subtotal: 5_000 })]).amount.toString()).toBe(
      '2000'
    );
    expect(calculate([line({ quantity: 6, subtotal: 6_000 })]).amount.toString()).toBe(
      '2000'
    );
  });

  test('allows free units without a purchase threshold', () => {
    expect(
      calculate([line({ quantity: 1, subtotal: 1_000 })], 100_000, {
        purchaseQuantity: 0,
        freeQuantity: 2,
      }).amount.toString()
    ).toBe('1000');
    expect(
      calculate([line({ quantity: 2, subtotal: 2_000 })], 100_000, {
        purchaseQuantity: 0,
        freeQuantity: 2,
      }).amount.toString()
    ).toBe('2000');
    expect(
      calculate([line({ quantity: 3, subtotal: 3_000 })], 100_000, {
        purchaseQuantity: 0,
        freeQuantity: 2,
      }).amount.toString()
    ).toBe('2000');
  });

  test('aggregates split lines for the same product', () => {
    const discount = calculate([
      line({ quantity: 2, subtotal: 2_000 }),
      line({ quantity: 3, subtotal: 3_000 }),
    ]);

    expect(discount.amount.toString()).toBe('2000');
  });

  test('applies the promotion independently to each matching product', () => {
    const discount = calculate([
      line({ productId: 'product_a', quantity: 4, subtotal: 4_000 }),
      line({ productId: 'product_b', quantity: 5, subtotal: 10_000 }),
    ]);

    expect(discount.amount.toString()).toBe('5000');
  });

  test('discounts the cheapest units when a product has different unit prices', () => {
    const discount = calculate([
      line({ quantity: 3, subtotal: 6_000 }),
      line({ quantity: 2, subtotal: 2_000 }),
    ]);

    expect(discount.amount.toString()).toBe('2000');
  });

  test('discounts across multiple price lines in cheapest-first order', () => {
    const discount = calculate(
      [line({ quantity: 5, subtotal: 10_000 }), line({ quantity: 2, subtotal: 2_000 })],
      100_000,
      { purchaseQuantity: 3, freeQuantity: 3 }
    );

    expect(discount.amount.toString()).toBe('4000');
  });

  test('supports fractional quantities proportionally', () => {
    const discount = calculate([line({ quantity: '4.5', subtotal: 4_500 })]);

    expect(discount.amount.toString()).toBe('1500');
  });

  test('ignores products without exact matching metadata', () => {
    const discount = calculate([
      line({ quantity: 5, subtotal: 5_000, metadata: { promotion: 'BOGO' } }),
      line({ quantity: 5, subtotal: 5_000, metadata: { Promotion: 'bogo' } }),
      line({ quantity: 5, subtotal: 5_000, metadata: { promotion: 'bogo' } }),
    ]);

    expect(discount.amount.toString()).toBe('2000');
  });

  test('ignores missing products, non-positive quantities, and currency mismatches', () => {
    const missingProduct: Commerce.DiscountCalculation.DiscountableLineItem = {
      subtotal: { amount: Decimal.from(5_000), currency: 'usd' },
      quantity: Decimal.from(5),
      period,
      price: { id: 'price_missing_product', metadata: {}, tiers: [] },
    };
    const discount = calculate([
      missingProduct,
      line({ quantity: 0, subtotal: 5_000 }),
      line({ quantity: 5, subtotal: 5_000, currency: 'eur' }),
    ]);

    expect(discount.amount.toString()).toBe('0');
  });

  test.each([
    ['purchase quantity', { purchaseQuantity: -1 }],
    ['free quantity', { freeQuantity: 0 }],
    ['metadata key', { metadataMatcher: { key: '', value: 'bogo' } }],
  ] satisfies [string, Partial<BuyXGetYFreeConfig>][])(
    'returns zero when the configured %s is invalid',
    (_label, override) => {
      const discount = calculate(
        [line({ quantity: 5, subtotal: 5_000 })],
        100_000,
        override
      );

      expect(discount.amount.toString()).toBe('0');
    }
  );

  test.each([0, -2])(
    'ignores a line with quantity %s without changing the qualifying product total',
    (quantity) => {
      const discount = calculate([
        line({ quantity: 4, subtotal: 4_000 }),
        line({ quantity, subtotal: 2_000 }),
      ]);

      expect(discount.amount.toString()).toBe('1000');
    }
  );

  test.each([0, -100])(
    'ignores a line with subtotal %s without consuming free quantity',
    (subtotal) => {
      const discount = calculate([
        line({ quantity: 4, subtotal: 4_000 }),
        line({ quantity: 100, subtotal }),
      ]);

      expect(discount.amount.toString()).toBe('1000');
    }
  );

  test('matches line-item and invoice currencies case-insensitively', () => {
    const discount = calculate([
      line({ quantity: 4, subtotal: 4_000, currency: 'USD' as Billing.Currency }),
    ]);

    expect(discount.amount.toString()).toBe('1000');
    expect(discount.currency).toBe('usd');
  });

  test.each([0, -1_000])('returns zero for a gross amount of %s', (grossAmount) => {
    const discount = calculate([line({ quantity: 5, subtotal: 5_000 })], grossAmount);

    expect(discount.amount.toString()).toBe('0');
  });

  test('caps the aggregate discount at the invoice total', () => {
    const discount = calculate(
      [
        line({ productId: 'product_a', quantity: 5, subtotal: 5_000 }),
        line({ productId: 'product_b', quantity: 5, subtotal: 5_000 }),
      ],
      3_000
    );

    expect(discount.amount.toString()).toBe('3000');
  });
});

import { describe, expect, test } from 'vitest';
import type { Billing, Commerce, Context } from '@stripe/extensibility-sdk';
import { Decimal } from '@stripe/extensibility-sdk';

import PriceTargetedAmountOff, { type PriceTargetedAmountOffConfig } from './index.js';

const context: Context = { type: 'script', id: 'test', livemode: false };
const period = { value: 'oneTime' as const, at: new Date('2026-01-01T00:00:00Z') };

function line(
  subtotal: number,
  metadata: Record<string, string>,
  currency: Billing.Currency = 'usd',
  quantity = 1
): Commerce.DiscountCalculation.DiscountableLineItem {
  return {
    subtotal: { amount: Decimal.from(subtotal), currency },
    quantity: Decimal.from(quantity),
    period,
    price: { id: `price_${subtotal}`, metadata, tiers: [] },
  };
}

const config: PriceTargetedAmountOffConfig = {
  fixedAmountOff: { amount: Decimal.from(1_500), currency: 'usd' },
  metadataMatcher: {
    key: 'promotion',
    value: 'summer',
  },
};

function calculate(
  lineItems: Commerce.DiscountCalculation.DiscountableLineItem[],
  override: Partial<PriceTargetedAmountOffConfig> = {},
  grossAmount = 100_000
) {
  return new PriceTargetedAmountOff().computeDiscounts(
    {
      grossAmount: { amount: Decimal.from(grossAmount), currency: 'usd' },
      lineItems,
      subscriptions: {},
    },
    { ...config, ...override },
    context
  ).discount.amount;
}

describe('PriceTargetedAmountOff', () => {
  test('applies the fixed amount once per matching line item', () => {
    const discount = calculate([
      line(4_000, { promotion: 'summer' }),
      line(6_000, { promotion: 'summer' }),
      line(6_000, { promotion: 'winter' }),
    ]);

    expect(discount.amount.toString()).toBe('3000');
  });

  test('caps each application at its matching line subtotal', () => {
    const discount = calculate([
      line(500, { promotion: 'summer' }),
      line(2_000, { promotion: 'summer' }),
    ]);

    expect(discount.amount.toString()).toBe('2000');
  });

  test('matches metadata exactly', () => {
    const discount = calculate([
      line(4_000, { Promotion: 'summer' }),
      line(4_000, { promotion: 'Summer' }),
      line(4_000, { promotion: 'summer' }),
    ]);

    expect(discount.amount.toString()).toBe('1500');
  });

  test('returns zero when the configured currency does not match', () => {
    const discount = calculate([line(4_000, { promotion: 'summer' })], {
      fixedAmountOff: { amount: Decimal.from(1_500), currency: 'eur' },
    });

    expect(discount.amount.toString()).toBe('0');
  });

  test('applies the fixed amount once per line regardless of quantity', () => {
    const discount = calculate([line(8_000, { promotion: 'summer' }, 'usd', 4)]);

    expect(discount.amount.toString()).toBe('1500');
  });

  test.each([
    [
      'fixed amount is zero',
      { fixedAmountOff: { amount: Decimal.zero, currency: 'usd' } },
    ],
    [
      'fixed amount is negative',
      { fixedAmountOff: { amount: Decimal.from(-500), currency: 'usd' } },
    ],
    ['metadata key is empty', { metadataMatcher: { key: '', value: 'summer' } }],
  ] satisfies [string, Partial<PriceTargetedAmountOffConfig>][])(
    'returns zero when the configured %s',
    (_label, override) => {
      const discount = calculate([line(4_000, { promotion: 'summer' })], override);

      expect(discount.amount.toString()).toBe('0');
    }
  );

  test('ignores lines without a price or with a different currency', () => {
    const withoutPrice: Commerce.DiscountCalculation.DiscountableLineItem = {
      subtotal: { amount: Decimal.from(4_000), currency: 'usd' },
      quantity: Decimal.from(1),
      period,
    };
    const discount = calculate([
      withoutPrice,
      line(4_000, { promotion: 'summer' }, 'eur'),
      line(4_000, { promotion: 'summer' }),
    ]);

    expect(discount.amount.toString()).toBe('1500');
  });

  test('ignores a matching line with a negative subtotal', () => {
    const discount = calculate([
      line(-500, { promotion: 'summer' }),
      line(4_000, { promotion: 'summer' }),
    ]);

    expect(discount.amount.toString()).toBe('1500');
  });

  test('ignores a matching line with a zero subtotal', () => {
    const discount = calculate([
      line(0, { promotion: 'summer' }),
      line(4_000, { promotion: 'summer' }),
    ]);

    expect(discount.amount.toString()).toBe('1500');
  });

  test('matches configured and line-item currencies case-insensitively', () => {
    const discount = calculate(
      [line(4_000, { promotion: 'summer' }, 'USD' as Billing.Currency)],
      {
        fixedAmountOff: {
          amount: Decimal.from(1_500),
          currency: 'USD' as Billing.Currency,
        },
      }
    );

    expect(discount.amount.toString()).toBe('1500');
    expect(discount.currency).toBe('usd');
  });

  test.each([0, -1_000])('returns zero for a gross amount of %s', (grossAmount) => {
    const discount = calculate([line(4_000, { promotion: 'summer' })], {}, grossAmount);

    expect(discount.amount.toString()).toBe('0');
  });

  test('caps the aggregate discount at the invoice total', () => {
    const discount = calculate(
      [line(4_000, { promotion: 'summer' }), line(4_000, { promotion: 'summer' })],
      {},
      2_000
    );

    expect(discount.amount.toString()).toBe('2000');
  });
});

import { defineConfig } from 'vitest/config';
import { existsSync, readdirSync } from 'fs';

const extensionProjects = existsSync('extensions')
  ? readdirSync('extensions')
      .filter((name) => existsSync(`extensions/${name}/package.json`))
      .map((name) => `extensions/${name}`)
  : [];

const projects = extensionProjects;

export default projects.length > 0
  ? defineConfig({
      test: {
        projects,
        passWithNoTests: true,

        // Only run tests from src, not compiled dist
        exclude: ['**/node_modules', '**/dist'],
        // Place snapshots alongside test files instead of in __snapshots__
        snapshotFormat: {
          escapeString: false,
          printBasicPrototype: false,
        },
        resolveSnapshotPath: (testPath, snapExtension) => {
          return testPath.replace(/\.test\.ts$/, `.test${snapExtension}`);
        },
      },
    })
  : defineConfig({ test: { passWithNoTests: true, include: [] } });

import { defineConfig } from 'vitest/config';
import { existsSync, readdirSync } from 'fs';
import { dirname, resolve } from 'path';
import { fileURLToPath } from 'url';

const rootDir = dirname(fileURLToPath(import.meta.url));
const extensionsDir = resolve(rootDir, 'extensions');

const extensionProjects = existsSync(extensionsDir)
  ? readdirSync(extensionsDir)
      .filter((name) => existsSync(resolve(extensionsDir, name, 'package.json')))
      .map((name) => resolve(extensionsDir, name))
  : [];

const projects = extensionProjects;

if (projects.length === 0) {
  console.debug(`No vitest projects detected. This means either:
- You have no extension projects defined, in which case this warning is expected.
- There is an internal error detecting vitest projects relative to the project root
  ${rootDir}.
`);
}

export default projects.length > 0
  ? defineConfig({
      test: {
        projects,
        passWithNoTests: true,
        setupFiles: ['@stripe/extensibility-test-helpers/vitest'],

        // Only run tests from src, not compiled dist
        exclude: ['**/node_modules', '**/dist'],
        // Place snapshots alongside test files instead of in __snapshots__
        snapshotFormat: {
          escapeString: false,
          printBasicPrototype: false,
        },
        resolveSnapshotPath: (testPath, snapExtension) => {
          return testPath.replace(/\.test\.ts$/, `.test${snapExtension}`);
        },
      },
    })
  : defineConfig({ test: { passWithNoTests: true, include: [] } });

